// Mirrors backend/app/schemas (contracts.py, claims.py).
// TODO(Kissa): replace with types generated by `npx openapi-typescript`.

export type Role = 'citizen' | 'helper' | 'officer' | 'admin' | 'auditor'
export type Route = 'AUTO_APPROVE' | 'ASK_PROOF' | 'UNSURE'
export type DocumentKind = 'death_certificate' | 'claimant_cnic' | 'frc' | 'nikah_nama'

export type SessionUser = { id: string; name: string; role: Role; tenant_id: string; person_id: string | null }
export type LoginResult = { access_token: string; refresh_token: string; user: SessionUser }

export type Me = {
  id: string
  role: Role
  name: string | null
  person: { id: string; cnic: string; name: string } | null
}

export type Family = { id: string; cnic: string; name: string }

export type DecisionSummary = {
  id: string
  route: Route
  reason_codes: string[]
  confidence: number
  rule_version: number
  model_id: string | null
  created_at: string
}

export type CaseView = {
  id: string
  reference: string
  status: string
  priority: number
  confidence: number | null
  claimant_person_id: string
  assigned_officer_id: string | null
  deceased_cnic: string | null
  created_at: string
  latest_decision: DecisionSummary | null
}

export type Explanation = { reason_code: string; text_ur: string; text_en: string; audio_key: string; icon: string }

export type CitizenExplanation = {
  case_reference: string
  status: string
  route: Route | null
  explanations: Explanation[]
  missing_items: string[]
  entitlement_end: string | null
}

export type ClaimIn = {
  claimant_cnic: string
  claimant_name: string
  relation_claimed: 'widow' | 'son' | 'daughter'
  deceased_cnic: string | null
  deceased_name: string
  payout_iban: string
  documents: DocumentKind[]
}

export type AuditRow = {
  seq: number
  ts: string
  actor_type: string
  role: string | null
  action: string
  resource: string | null
  details: Record<string, unknown>
}
